public static class CustomerOrdersQuery
{
    public const string Sql = """
        SELECT c.id, c.name, o.total, o.order_date, o.status
        FROM customers c
        JOIN orders o ON o.customer_id = c.id
        WHERE c.id = @p1 AND o.total > @p2
        ORDER BY o.order_date DESC
        """;

    // Column names use snake_case: enable Dapper.DefaultTypeMap.MatchNamesWithUnderscores = true once at startup.
    public static async Task<IReadOnlyList<CustomerOrdersRow>> GetCustomerOrdersAsync(this IDbConnection db, long p1, decimal p2, CancellationToken ct = default) =>
        (await db.QueryAsync<CustomerOrdersRow>(new CommandDefinition(Sql, new { p1, p2 }, cancellationToken: ct))).AsList();
}

public sealed class OrdersOfRow
{
    public long? Id { get; set; }

    public DateTimeOffset? OrderDate { get; set; }

    public decimal? Total { get; set; }
}

public sealed record AddOrderLineResult(int? LineNo);

/// <summary>Procedures and functions of public.</summary>
public static partial class PublicProcedures
{
    /// <summary>Calls public.fn_tax.</summary>
    public static Task<decimal?> FnTaxAsync(this IDbConnection db, decimal amount, CancellationToken ct = default) =>
        db.ExecuteScalarAsync<decimal?>(new CommandDefinition("SELECT public.fn_tax(@amount)", new { amount }, cancellationToken: ct));

    /// <summary>Calls public.fn_tax.</summary>
    public static Task<decimal?> FnTaxAsync(this IDbConnection db, decimal amount, decimal rate, CancellationToken ct = default) =>
        db.ExecuteScalarAsync<decimal?>(new CommandDefinition("SELECT public.fn_tax(@amount, @rate)", new { amount, rate }, cancellationToken: ct));

    /// <summary>Calls public.orders_of.</summary>
    public static async Task<IReadOnlyList<OrdersOfRow>> OrdersOfAsync(this IDbConnection db, long customerId, CancellationToken ct = default) =>
        (await db.QueryAsync<OrdersOfRow>(new CommandDefinition("SELECT id, order_date AS \"OrderDate\", total FROM public.orders_of(@p_customer_id)", new { p_customer_id = customerId }, cancellationToken: ct))).AsList();

    /// <summary>Calls public.add_order_line.</summary>
    public static async Task<AddOrderLineResult> AddOrderLineAsync(this IDbConnection db, long orderId, int productId, int? qty = null, int? lineNo = null, CancellationToken ct = default)
    {
        var callArgs = new List<string> { "@p_order_id", "@p_product_id" };
        if (qty is not null) callArgs.Add("p_qty => @p_qty");
        if (lineNo is not null) callArgs.Add("p_line_no => @p_line_no");
        var sql = $"CALL public.add_order_line({string.Join(", ", callArgs)})";
        // OUT / INOUT values come back as one row.
        var row = (IDictionary<string, object?>)await db.QuerySingleAsync(new CommandDefinition(sql, new { p_order_id = orderId, p_product_id = productId, p_qty = qty, p_line_no = lineNo }, cancellationToken: ct));
        return new AddOrderLineResult(row["p_line_no"] is null or DBNull ? (int?)null : Convert.ToInt32(row["p_line_no"]));
    }
}

/// <summary>
/// Lets Dapper pass Npgsql-native values straight to the provider. Register once at startup:
/// <c>SqlMapper.AddTypeHandler(new NpgsqlPassThroughHandler&lt;IPAddress&gt;());</c>
/// <c>SqlMapper.AddTypeHandler(new NpgsqlPassThroughHandler&lt;PhysicalAddress&gt;());</c>
/// </summary>
public sealed class NpgsqlPassThroughHandler<T> : SqlMapper.TypeHandler<T>
{
    public override void SetValue(IDbDataParameter parameter, T? value) => parameter.Value = (object?)value ?? DBNull.Value;

    public override T? Parse(object value) => (T)value;
}
